"use geosolve sketch";
import { sketch, mm, rad } from "@geosolve/sketch-code";

export default sketch(($) => {
  const point1Start = $.geometry.sketchPoint("point1Start", {
    point: [0, 0],
    label: "start",
  });
  const point2End = $.geometry.sketchPoint("point2End", {
    point: [4, 0],
    label: "end",
  });
  const curve1Support = $.geometry.segment("curve1Support", {
    start: point1Start.point,
    end: point2End.point,
    branchDirection: [1, 0],
    label: "support",
    role: "profile",
  });
  const operationTrim1 = $.operation.trim("operationTrim1", {
    source: curve1Support.span,
    parameter: 0.25,
    retained: "after",
  });
  const operationTrim2 = $.operation.trim("operationTrim2", {
    source: operationTrim1.retained,
    parameter: 0.75,
    retained: "before",
  });
  $.group("Points", [point1Start, point2End]);
  $.group("Geometry", [curve1Support]);
  return {};
});
